PROGRAM ST230_MONTERINGSSTATION
VAR
    steg      : INT := 0;
    xPrg      : INT := 1;
    xStartA   : BOOL := FALSE;
    xStartB   : BOOL := FALSE;
    xSpann    : BOOL := FALSE;
    xStopp    : BOOL := FALSE;
    tmrSpann  : TON;
END_VAR

(* EMG_OK och AIR_OK lases bara. Logiken forreglas AV nodstoppskretsen och
   tryckluftsvakten; den bar ingen sakerhetsfunktion sjalv. *)

(* Vakten mot utebliven lagesgivare: 2,0 s, alltsa spannarens 0,6 s med
   god marginal. Rakningen borjar nar spannaren kommenderas och slutar nar
   ST230_CLP_CLOSED bekrastar. *)
tmrSpann(IN := xSpann AND NOT ST230_CLP_CLOSED, PT := T#2000ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    xStartA := FALSE;
    xStartB := FALSE;
    xSpann := FALSE;
    xPrg := 1;
    steg := 0;
ELSE
    CASE steg OF
        0:
            IF EMG_OK AND AIR_OK THEN
                steg := 1;
            END_IF;
        1:
            (* Program A: hamta del A och lagg den i fixturen. *)
            xStartA := TRUE;
            steg := 2;
        2:
            IF ST230_RB_DONE AND ST230_PRT_A_PRS THEN
                xStartA := FALSE;
                xSpann := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST230_CLP_CLOSED AND ST230_CLP_FORCE >= 400.0
                    AND ST230_CLP_FORCE <= 1100.0 THEN
                xPrg := 2;
                xStartB := TRUE;
                steg := 4;
            ELSIF ST230_CLP_CLOSED AND (ST230_CLP_FORCE < 400.0
                    OR ST230_CLP_FORCE > 1100.0) THEN
                (* Spant lage utan kraft, eller overkraft mot konsolen:
                   spannaren slapps och del B laggs aldrig in. *)
                xSpann := FALSE;
                xStopp := TRUE;
                steg := 9;
            ELSIF tmrSpann.Q THEN
                (* Lagesgivaren uteblir: vakten 2,0 s ar runnit. *)
                xSpann := FALSE;
                xStopp := TRUE;
                steg := 9;
            END_IF;
        4:
            IF ST230_RB_DONE AND ST230_PRT_B_PRS THEN
                xStartB := FALSE;
                steg := 5;
            END_IF;
        5:
            IF NOT ST230_PRT_B_PRS THEN
                xSpann := FALSE;
                xPrg := 1;
                steg := 0;
            END_IF;
        9:
            (* Last til manuell atgard. *)
            xSpann := FALSE;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* En skrivning per utgang, forreglingarna i samma uttryck (F7-doktrinen):
   spannaren kommenderas bara med del A i fixturen, B-programmet bara nar
   stationen inte ar stoppad, och programnumret foljer sekvensens fase. *)
ST230_RB_PRG := xPrg;
ST230_RB_START := (xStartA OR xStartB) AND EMG_OK AND AIR_OK AND NOT xStopp;
ST230_CLP_CLOSE := xSpann AND ST230_PRT_A_PRS AND EMG_OK AND AIR_OK;
END_PROGRAM

